"""Summarise the SYNTHETIC VOICE stand-in gate run (results/gate_synthvoice2). Writes results/gate_synthvoice2_summary.md. NOT the human gate."""
import json, glob, collections
D = "results/gate_synthvoice2"
rows = [json.loads(l) for f in sorted(glob.glob(D + "/results_w*.jsonl")) for l in open(f)]
cl = [json.loads(l) for f in sorted(glob.glob(D + "/diag_clean_w*.jsonl")) for l in open(f)]
def ok(p, t): return p is not None and bool(t) and p.get("crop") == t.get("crop") and p.get("price") == t.get("price")
def okp(p, t): return ok(p, t) and p.get("place") == t.get("place")
def marg(r):
    a = r["con_alts"]; top = a[0]
    o = [x[2] for x in a[1:] if x[1].get("price") != top[1].get("price") or x[1].get("crop") != top[1].get("crop")]
    return top[2] - max(o) if o else 10.0
def acc(r): return marg(r) >= 2.0 and r["lp_con"] - r["lp_free"] >= -25.0
L = ["| condition | free ASR + fuzzy parser: crop AND price | closed-grammar decoder: crop AND price | closed-grammar, crop AND price AND place | demo abstain rule: accepted / correct / wrong accepted |", "|---|---|---|---|---|"]
for name, R, label in (("clean", cl, "no channel (supplementary diagnostic, not part of the gate)"), ("20", None, "SIMULATED FM 20 dB"), ("12", None, "SIMULATED FM 12 dB (gate condition)"), ("8", None, "SIMULATED FM 8 dB")):
    if R is None: R = [r for r in rows if r["cond"] == name]
    G = [r for r in R if r["truth"]]; A = [r for r in G if acc(r)]
    L.append(f"| {label} | {sum(ok(r['free_parse'], r['truth']) for r in G)}/{len(G)} | {sum(ok(r['con_parse'], r['truth']) for r in G)}/{len(G)} | {sum(okp(r['con_parse'], r['truth']) for r in G)}/{len(G)} | {len(A)} / {sum(ok(r['con_parse'], r['truth']) for r in A)} / {sum(not ok(r['con_parse'], r['truth']) for r in A)} |")
ab = ["| sentence | condition | margin | gap | demo rule decision |", "|---|---|---|---|---|"]
na = 0
for r in sorted([r for r in rows if not r["truth"] and r["id"] in ("g21", "g22")], key=lambda r: (r["id"], -int(r["cond"]))):
    g = r["lp_con"] - r["lp_free"]; d = "accepted" if acc(r) else "ABSTAIN"; na += d == "ABSTAIN"
    ab.append(f"| {r['id']} ({'coffee' if r['id']=='g21' else 'weather news'}) | {r['cond']} dB | {marg(r):.1f} | {g:.1f} | {d} |")
byid = collections.defaultdict(dict)
for r in rows:
    if r["truth"]: byid[r["id"]][r["cond"]] = (ok(r["con_parse"], r["truth"]), r)
F = ["| sentence | truth | closed-grammar output at 20 / 12 / 8 dB | right at 20/12/8 |", "|---|---|---|---|"]
for k in sorted(byid):
    d = byid[k]
    if all(d[c][0] for c in ("20", "12", "8")): continue
    t = d["12"][1]["truth"]; f = lambda c: d[c][1]["con_parse"]; s = lambda p: f"{p['crop']} {p['place']} {p['price']}"
    F.append(f"| {k} | {t['crop']} {t['place']} {t['price']} | {s(f('20'))} / {s(f('12'))} / {s(f('8'))} | {''.join('Y' if d[c][0] else 'n' for c in ('20','12','8'))} |")
lost = collections.Counter(); wrongcrop = 0; swap = 0
for r in rows:
    if r["truth"] and not ok(r["con_parse"], r["truth"]):
        p, t = r["con_parse"], r["truth"]
        if p.get("crop") != t["crop"]: wrongcrop += 1
        elif p.get("price") is not None and p["price"] < t["price"] / 5: lost[r["cond"]] += 1
        else: swap += 1
nl = sum(lost.values()); nf = sum(1 for r in rows if r["truth"] and not ok(r["con_parse"], r["truth"]))
open("results/gate_synthvoice2_summary.md", "w").write("\n".join([
"**SYNTHETIC VOICE stand-in. This is NOT the human gate.** The human gate (Tejas's own recording) has not been run.", "",
"Audio: `recording/synthetic_recording.wav`, 22 sentences from `recording/sentences.txt` in order, about 3 s silence between, one continuous 16 kHz mono file (229 s), generated by `eval/make_synth_recording.py`. TTS: `Mwau/waxal_swahili-tts-mms` (VITS, single speaker, fine-tuned from `facebook/mms-tts-swh` on the WAXAL `swa_tts` data; licence CC-BY-NC-4.0, inherited from the MMS base; non-commercial use for test material only). The earlier dry run used `facebook/mms-tts-swh` with random speed/pitch; this run uses different weights and a different voice at default speed. Exact gate pipeline: `eval/gate_prepare.py` (22 of 22 segments found, no manual mapping) -> `eval/run_eval.py` at 20, 12 and 8 dB SIMULATED FM CNR -> `eval/gate_report.py` (`results/gate_synthvoice2/report.md`). The clean-audio row was run afterwards as a diagnostic with the same script (`diag_clean_w*.jsonl`).", "",
"Gate rule (set before the run): GO if either route gets crop AND exact price right in at least 16 of 20 at 12 dB. **Result on this synthetic voice: NO-GO** (closed-grammar 11/20, free + parser 0/20 at 12 dB).", "", *L, "",
"The gate counts crop and price only. Place is also shown because the product reports it; g18 (Kampala) came out as Mbeya in all three conditions, which the gate counts as correct.", "",
f"Abstain tests, sentences 21 (coffee) and 22 (weather news), which are outside the vocabulary: the demo rule (margin >= 2.0 and gap >= -25.0) abstained on {na} of 6 clips.", "", *ab, "",
"Note the margin alone would have accepted g22 at 12 dB (3.5); the likelihood gap is what rejected it. g21 at 20 dB was rejected by the margin (0.8) although its gap (-16.9) was within the threshold.", "",
f"Failures of the closed-grammar decoder over all 60 gate decodes ({nf} wrong): {nl} where the price came out far smaller than the truth (the thousand word 'elfu' and what precedes it were lost, e.g. 'elfu tatu na mia tano' -> 'ishirini na tatu'; {lost['20']} at 20 dB, {lost['12']} at 12 dB, {lost['8']} at 8 dB), {swap} other number-word swaps (e.g. mbili <-> nne in g01), {wrongcrop} wrong crop (g17 at 12 and 8 dB, g13 at 8 dB). The clean-audio diagnostic also scores only 13/20, so the simulated channel is not the main cause here; the 8 dB row is 3 clips lower than clean.", "",
"Sentences that failed in at least one condition (closed-grammar route):", "", *F, "",
"Reading (INFERENCE, not verified by listening to the file or testing another model): the free transcripts of this voice are poor even on clean audio (2/20 correct), e.g. g08 'elfu tatu na mia tano' was heard as 'kwa watatu na ni antano', so this voice is much harder for the recogniser than the earlier synthetic voice (18-19/20 closed-grammar). Candidate causes (UNKNOWN which): how this voice pronounces the number words, and the recogniser being fine-tuned on Common Voice read speech; in the failures the decoder chose a shorter number that drops 'elfu'. What this does show (FACT): the 36/36 and 19/20 results on the first synthetic voice do not transfer to a different synthetic voice, so they must not be read as evidence about human speakers. With the demo abstain rule, 5 of the 13 accepted clips at 12 dB still carried a wrong crop or price, so abstaining did not protect against these errors; the human confirm step is what would. The human gate is still required, and the same weakness (lost thousands) is the first thing to check on it.", ""]))
print(open("results/gate_synthvoice2_summary.md").read())
